import { defineCommand } from "@core/command";
import { FlagSpec } from "@lib/args";
import { downloadMediaMessage, type WAMessage } from "baileys";

export default defineCommand({
  name: "sticker",
  description: "Sticker maker",
  category: "tools",
  aliases: ["s", "stiker"],
  flags: [
    FlagSpec.value(["--packname", "-p"]).description(
      "Sticker pack name (default: arsa)",
    ),
    FlagSpec.value(["--author", "-a"]).description(
      "Author name (default: generated by: violajs)",
    ),
    FlagSpec.value(["--fit", "-f"]).description(
      "How to fit to 512px: inside (keep ratio, default) or fill (stretch to 512x512)",
    ),
    FlagSpec.value(["--rotate", "-r"]).description(
      "Rotate clockwise, in multiples of 90 degrees (example: 90, 180, -90)",
    ),
    FlagSpec.bool(["--flip"]).description("Flip image top-bottom (vertical)"),
    FlagSpec.bool(["--flop"]).description("Flip image left-right (horizontal)"),
  ],
  execute: async (ctx) => {
    const packname = ctx.args?.value("--packname") ?? "arsa";
    const author = ctx.args?.value("--author") ?? "generated by: violajs";

    const ctxInfo = ctx.msg.message?.extendedTextMessage?.contextInfo;
    const quoted = ctxInfo?.quotedMessage;
    let sources: WAMessage[] = [];
    if (ctx.msg.message?.imageMessage) {
      sources = [ctx.msg];
    } else if (quoted?.imageMessage || quoted?.stickerMessage) {
      sources = [
        {
          key: {
            remoteJid: ctx.msg.key.remoteJid,
            id: ctxInfo?.stanzaId,
            participant: ctxInfo?.participant,
          },
          message: quoted,
        },
      ];
    }

    if (sources.length === 0) return;

    const isflip = ctx.args?.has("--flip") ?? false;
    const isflop = ctx.args?.has("--flop") ?? false;

    const fit: "fill" | "inside" =
      ctx.args?.value("--fit")?.toLowerCase() === "fill" ? "fill" : "inside";

    const degrees = Number(ctx.args?.value("--rotate") ?? 0);
    const rotate =
      Number.isInteger(degrees) && degrees % 90 === 0
        ? ((degrees % 360) + 360) % 360
        : 0;

    const transform = isflip || isflop || rotate !== 0 || fit === "fill";
    const exif = createExif(packname, author);

    for (const source of sources) {
      const media = await downloadMediaMessage(source, "buffer", {});
      const sticker = source.message?.stickerMessage;

      let webp: Uint8Array;
      if (sticker && (sticker.isAnimated || !transform)) {
        webp = media;
      } else {
        const img = new Bun.Image(media);
        if (isflip) img.flip();
        if (isflop) img.flop();
        if (rotate) img.rotate(rotate);
        img.resize(512, 512, { fit });
        webp = await img.webp().buffer();
      }

      await ctx.send.sticker(embedExif(webp, exif));
    }
  },
});

function createExif(packname: string, author: string): Buffer {
  const json = Buffer.from(
    JSON.stringify({
      "sticker-pack-id": "violajs-sticker-pack",
      "sticker-pack-name": packname,
      "sticker-pack-publisher": author,
    }),
    "utf8",
  );

  const header = Buffer.from([
    0x49, 0x49, 0x2a, 0x00, 0x08, 0x00, 0x00, 0x00, 0x01, 0x00, 0x41, 0x57,
    0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x16, 0x00, 0x00, 0x00,
  ]);
  header.writeUInt32LE(json.length, 14);

  return Buffer.concat([header, json]);
}

const VP8X_ALPHA = 0x10;
const VP8X_EXIF = 0x08;

function riffChunk(id: string, data: Uint8Array): Buffer {
  const head = Buffer.alloc(8);
  head.write(id, 0, "ascii");
  head.writeUInt32LE(data.length, 4);
  const pad = data.length & 1 ? Buffer.alloc(1) : Buffer.alloc(0);
  return Buffer.concat([head, data, pad]);
}

function makeVp8x(image: { id: string; data: Buffer }): Buffer {
  let width: number;
  let height: number;
  let flags = 0;

  if (image.id === "VP8L") {
    const bits = image.data.readUInt32LE(1);
    width = (bits & 0x3fff) + 1;
    height = ((bits >>> 14) & 0x3fff) + 1;
    if ((bits >>> 28) & 1) flags |= VP8X_ALPHA;
  } else if (image.id === "VP8 ") {
    width = image.data.readUInt16LE(6) & 0x3fff;
    height = image.data.readUInt16LE(8) & 0x3fff;
  } else {
    throw new Error(`unsupported WebP chunk: ${image.id}`);
  }

  const body = Buffer.alloc(10);
  body[0] = flags;
  body.writeUIntLE(width - 1, 4, 3);
  body.writeUIntLE(height - 1, 7, 3);
  return body;
}

function embedExif(webp: Uint8Array, exif: Uint8Array): Buffer {
  const src = Buffer.from(webp);
  if (
    src.toString("ascii", 0, 4) !== "RIFF" ||
    src.toString("ascii", 8, 12) !== "WEBP"
  ) {
    throw new Error("not a WebP file");
  }

  const chunks: { id: string; data: Buffer }[] = [];
  for (let p = 12; p + 8 <= src.length;) {
    const id = src.toString("ascii", p, p + 4);
    const size = src.readUInt32LE(p + 4);
    chunks.push({ id, data: src.subarray(p + 8, p + 8 + size) });
    p += 8 + size + (size & 1);
  }

  if (chunks[0]?.id !== "VP8X") {
    chunks.unshift({ id: "VP8X", data: makeVp8x(chunks[0]!) });
  }

  const kept = chunks.filter((c) => c.id !== "EXIF");
  const vp8x = Buffer.from(kept[0]!.data);
  vp8x[0]! |= VP8X_EXIF;
  kept[0] = { id: "VP8X", data: vp8x };

  const body = Buffer.concat([
    ...kept.map((c) => riffChunk(c.id, c.data)),
    riffChunk("EXIF", exif),
  ]);

  const head = Buffer.alloc(12);
  head.write("RIFF", 0, "ascii");
  head.writeUInt32LE(4 + body.length, 4);
  head.write("WEBP", 8, "ascii");
  return Buffer.concat([head, body]);
}
